// ---------- P3 Clinical conditions, lessons 9–12: addiction, psychosis, grief, suicide prevention ----------
// Evidence checked on PubMed (29 Oct 2026). Summa quotations: Dominican translation, checked by script against New Advent.
addTerms([
 {id:"sud",t:"Substance use disorder",la:"",d:"Psychology",b:"A pattern of substance use causing clinically significant impairment or distress, graded mild, moderate or severe by the number of criteria met.",p:"DSM-5-TR lists 11 criteria in four groups: impaired control, social impairment, risky use, and pharmacological criteria (tolerance, withdrawal); 2–3 = mild, 4–5 = moderate, 6+ = severe. ICD-11 distinguishes harmful pattern of use from dependence.",ex:"Drinking more than intended, failed attempts to cut down, and missing lectures because of hangovers.",where:"DSM-5-TR; ICD-11",ccc:"2290–2291",conf:"Any use; or moral failure only.",rel:["imputability","temperance"],lesson:"p3l9",alias:["addiction","substance use disorder","alcohol use disorder","dependence","SUD"]},
 {id:"motivational-interviewing",t:"Motivational interviewing",la:"",d:"Psychology",b:"A collaborative conversation style for strengthening a person's own motivation and commitment to change.",p:"Developed by Miller and Rollnick. Core skills: open questions, affirmations, reflections, summaries (OARS); evoking 'change talk'; rolling with resistance rather than arguing. Widely used for substance use and health behaviour.",ex:"\"On a scale of 0–10, how important is it to you to cut down? Why a 6 and not a 3?\"",where:"Miller and Rollnick (2013)",ccc:"",conf:"Confrontation or lecturing.",rel:["sud"],lesson:"p3l9",alias:["motivational interviewing","MI","change talk","OARS"]},
 {id:"psychosis",t:"Psychosis",la:"",d:"Psychology",b:"A state in which a person's contact with reality is seriously impaired, typically with delusions, hallucinations, or disorganised thinking.",p:"Found in schizophrenia-spectrum disorders, bipolar and depressive disorders with psychotic features, substance-induced and medical conditions (delirium, epilepsy, dementia). Negative symptoms (reduced motivation, emotion, speech) and cognitive deficits often cause the most lasting disability in schizophrenia.",ex:"Hearing voices commenting on one's actions; believing one's thoughts are broadcast.",where:"DSM-5-TR; ICD-11 6A20",ccc:"",conf:"Unusual religious belief shared by one's community; vivid imagination.",rel:["mental-disorder","imputability"],lesson:"p3l10",alias:["psychosis","schizophrenia","delusion","hallucination","psychotic"]},
 {id:"prolonged-grief",t:"Prolonged grief disorder",la:"",d:"Psychology",b:"Persistent, pervasive grief with intense longing or preoccupation with the deceased, lasting beyond cultural norms and causing impairment.",p:"ICD-11 6B42: at least 6 months after the loss; DSM-5-TR (2022): at least 12 months (adults), with symptoms such as identity disruption, disbelief, avoidance, intense emotional pain, numbness, meaninglessness, loneliness. About 1 in 10 bereaved adults after non-violent loss (Lundorff et al., 2017).",ex:"Two years after her husband's death, a widow cannot accept it, avoids everything that reminds her, and feels her life has no meaning.",where:"ICD-11; DSM-5-TR",ccc:"",conf:"Normal grief, which may be intense and long but gradually integrates.",rel:["sorrow"],lesson:"p3l11",alias:["prolonged grief","complicated grief","grief","bereavement"]},
 {id:"safety-plan",t:"Safety plan",la:"",d:"Psychology",b:"A brief, written, collaboratively made list of steps a person at risk of suicide can follow in a crisis.",p:"Stanley and Brown's Safety Planning Intervention: (1) warning signs; (2) internal coping strategies; (3) people and places for distraction; (4) people to ask for help; (5) professionals and crisis lines; (6) making the environment safer. With follow-up calls, associated with 45% fewer suicidal behaviours in a large cohort study (Stanley et al., 2018).",ex:"A card in one's wallet listing personal warning signs, a walk, two friends' numbers and a crisis line.",where:"Stanley et al. (2018)",ccc:"",conf:"'No-suicide contracts', which lack evidence.",rel:["prolonged-grief"],lesson:"p3l12",alias:["safety plan","safety planning","suicide prevention","suicide risk"]}
]);

